def build_sidebar(active_menu):
    states = {
        'equity_open': '', 'equity_vehicle_active': '', 'model_config_active': '',
        'insurance_open': '', 'pre_insurance_active': '', 'insurance_record_active': '', 'exception_record_active': '',
        'enjoyment_open': '', 'enjoyment_record_active': '', 'enjoyment_desc_active': '',
        'evidence_open': '', 'data_evidence_active': '', 'report_evidence_active': '',
        'data_verify_active': '', 'model_manage_active': '',
        'system_open': '', 'user_manage_active': '', 'role_permission_active': '', 'log_management_active': ''
    }
    active_map = {
        'equity_vehicle': ['equity_open', 'equity_vehicle_active'],
        'model_config': ['equity_open', 'model_config_active'],
        'pre_insurance': ['insurance_open', 'pre_insurance_active'],
        'insurance_record': ['insurance_open', 'insurance_record_active'],
        'exception_record': ['insurance_open', 'exception_record_active'],
        'enjoyment_record': ['enjoyment_open', 'enjoyment_record_active'],
        'enjoyment_desc': ['enjoyment_open', 'enjoyment_desc_active'],
        'data_evidence': ['evidence_open', 'data_evidence_active'],
        'report_evidence': ['evidence_open', 'report_evidence_active'],
        'data_verify': ['data_verify_active'],
        'model_manage': ['model_manage_active'],
        'user_manage': ['system_open', 'user_manage_active'],
        'role_permission': ['system_open', 'role_permission_active'],
        'log_management': ['log_management_active']
    }
    for key in active_map.get(active_menu, []):
        states[key] = 'active' if not key.endswith('_open') else 'open'
    result = SIDEBAR
    for k, v in states.items():
        result = result.replace('__' + k + '__', v)
    return result


def build_page(title, tab_title, active_menu, filters, status_tabs, table, total='10', page_buttons='<button class="page-btn" disabled>&lt;</button><button class="page-btn active">1</button><button class="page-btn" disabled>&gt;</button>'):
    html = HEAD.replace('__TITLE__', title)
    html += build_sidebar(active_menu)
    html += HEADER_TAB.replace('__TAB_TITLE__', tab_title)
    html += filters
    html += status_tabs
    html += table
    html += PAGINATION.replace('__TOTAL__', total).replace('__PAGE_BUTTONS__', page_buttons)
    html += FOOTER
    # Fix double curly braces left over from .format() migration
    html = html.replace('{{', '{').replace('}}', '}')
    return html


